import json,hashlib
from pathlib import Path
from datetime import datetime,timezone
from collections import Counter
O=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def save(p,d):p.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
assert not (O/'author-freeze.json').exists()
rows=[json.loads(p.read_text(encoding='utf-8'))for p in sorted(O.glob('scope-rank*.json'))]
assert [r['candidate_rank']for r in rows]==list(range(36,53))
ledger=O.parents[2]/'incoming-paper-monitor/ledger.json'
L=json.loads(ledger.read_text(encoding='utf-8'));states=[]
for r in rows:
 g=L['groups'][r['group_id']]
 assert g['review']['status']=='queued' and not g.get('needs_recheck')
 assert g['generation']==r['automated_nomination']['source_generation_in_partition']
 for p,h in r['bound_files'].items():assert sha(p)==h,(p,h)
 states.append({'rank':r['candidate_rank'],'group_id':r['group_id'],'status':g['review']['status'],'generation':g['generation'],'needs_recheck':g.get('needs_recheck')})
end=datetime.now(timezone.utc);start=datetime.fromisoformat(json.loads((O/'timing-start.json').read_text())['started_at'])
save(O/'final-selection-recheck.json',{'checked_at':end.isoformat(),'ledger_sha256':sha(ledger),'all_selected_queued':True,'all_generation_and_recheck_guards_pass':True,'states':states,'skipped_ranks':[],'terminal_policy':'Only queued scopes retained; all terminal statuses excluded, not only complete.'})
read={(c['source_sha256'],p)for r in rows for c in r['coverage']for p in c['pages_read']}
view={(c['source_sha256'],p)for r in rows for c in r['coverage']for p in c['pages_visually_inspected']}
sources={f['sha256']for r in rows for f in r['original_files']}
outcomes={k:0 for k in ['present','no_usable_in_inspected_main_and_si','referenced_only','unresolved']};outcomes.update(Counter(r['synthesis_outcome']for r in rows))
summary={'schema':'mattersyn-fast-methods-triage-summary/1','status':'author_screen_complete_independent_audit_pending','author':'/root/backlog_eta','started_at':start.isoformat(),'ended_at':end.isoformat(),'elapsed_seconds':round((end-start).total_seconds(),2),'timing_scope':'Actual elapsed includes resumed context, fresh hashes, targeted reading/views, receipts and checks. Selected atomic nominations only; not a corpus throughput or prevalence estimate.','scope_count':17,'distinct_articles':16,'source_copies':sum(len(r['original_files'])for r in rows),'unique_source_contents':len(sources),'pdf_pages_read':len(read),'pdf_pages_visually_inspected':len(view),'outcomes':outcomes,'distinct_article_synthesis_present':14,'duplicate_review_reuse':{'ranks':[45,46],'duplicate_scopes_beyond_unique_articles':1,'queue_aliases_created':0,'method':'Same main bytes reviewed once; both original paths rehashed and separate receipts retained.'},'attachment_handling':{'matched_SI_PDFs_selectively_read':6,'matched_DOCX_textually_inspected':1,'identical_DOCX_copies':2,'legacy_DOC_SI_unread':{'rank':43,'pairing':'unresolved','atomic_TableS1_claim':'unresolved_until_actual_SI_read'},'mislabeled_docx_ZIP_with_four_CIFs':38,'content_main_SI_roles_reversed_vs_filename':[39,40]},'local_experimental_target_atomic_candidates':[{'rank':38,'available':'four CIF coordinate-loop files','measurement_states':4,'chemical_compositions':2,'qualification':'Bulk crystals at room/low temperature, not automatically exfoliated-sheet structures; complete model and specimen links not validated.'},{'rank':49,'available':'two SI experimental fractional-coordinate tables','measurement_states':2,'qualification':'Ag-inter and Ag-NCs separate; upstream cluster recipe referenced, final structure relation to prior work and disorder/occupancies require review.'},{'rank':50,'available':'two experimental coordinate columns in Table1','measurement_states':2,'qualification':'Undoped host and0.5%Mn powder only; other loading recipes and GGA/LDA calculations are not additional measured coordinate sets.'}],'local_experimental_target_atomic_candidate_articles':3,'candidate_coordinate_measurement_contexts':8,'candidate_coordinate_contexts_are_not_approved_pairs':True,'partial_coordinate_parameter_articles':[41,51],'product_deposit_claim_without_local_array_established':[36,40,44],'unrelated_adjacent_article_atomic_false_transfer':47,'purchased_target_no_local_synthesis':52,'new_approved_structure_recipe_pairs':0,'full_source_reviews_completed':0,'training_admissions':0,'site_or_ledger_writes':False,'publication_and_training_states_changed_by_this_task':False,'priority_selection_prevalence_inference_allowed':False,'stopping_boundary':'All remaining eligible accepted atomic nominations through rank52 screened; no batch05 started.','rows':[{'rank':r['candidate_rank'],'doi':r['identity']['doi'],'title':r['identity']['title'],'outcome':r['synthesis_outcome'],'structure_tier':r['structure_tier'],'recommendation':r['recommendation'],'receipt':f"scope-rank{r['candidate_rank']:03d}.json",'receipt_sha256':sha(O/f"scope-rank{r['candidate_rank']:03d}.json")}for r in rows]}
save(O/'summary.json',summary)
md=f"# Batch04 Methods-first screening\n\nAuthor screening complete; independent audit pending. 17 queue scopes /16 articles:15 scopes (14 articles) have target preparation, one has referenced-only CdSe synthesis with current device fabrication, and one studies purchased gold without a synthesis in the supplied main. Zero approved pairs or source completions.\n\nActual elapsed {summary['elapsed_seconds']/60:.1f} minutes; {len(read)} distinct PDF pages read and {len(view)} visually inspected. Six SI PDFs were selectively read; one DOCX read as text; one legacy DOC remains unread/unpaired. These priority-selected results do not estimate corpus yield or throughput.\n\nThree articles have local experimental target-coordinate candidates: rank38 four CIF files for two bulk compositions at two temperatures; rank49 two Ag-cluster intermediate/product tables; rank50 two host/doped powder-refinement columns. Eight measurement contexts are not eight validated recipe pairs. Detailed completeness, disorder, constrained sites, model provenance and specimen links remain unverified. Ranks41/51 supply partial fitted coordinate parameters, not complete validated arrays. Ranks36/40/44 have product-deposit claims without local arrays established.\n\nRank38's .docx attachment is actually a ZIP containing CIF text files. Ranks39/40 have filename main/SI roles reversed. Rank43 points to a ZnO atom table in unread legacy SI, so it is unresolved rather than absent. Rank47's atomic table belongs to a different article on the same scanned page. Ranks45/46 are one byte-identical article reviewed once, with both queue scopes retained; no aliases or closures were created.\n\nAll selected scopes remain queued at matching generation without recheck holds; every bound original was rehashed. No shared ledger, canonical, website or training state was modified. No further batch started.\n\n"
md+='| Rank | DOI | Synthesis outcome | Structure scope |\n|---|---|---|---|\n'+''.join(f"| {r['candidate_rank']} | {r['identity']['doi']} | {r['synthesis_outcome']} | {r['structure_tier']} |\n"for r in rows)
(O/'summary.md').write_text(md,encoding='utf-8')
files={str(p):sha(p)for p in O.rglob('*')if p.is_file()and p.name!='author-freeze.json'}
save(O/'author-freeze.json',{'schema':'mattersyn-private-triage-freeze/1','created_at':datetime.now(timezone.utc).isoformat(),'author':'/root/backlog_eta','status':'author_screen_complete_independent_audit_pending','summary_sha256':sha(O/'summary.json'),'bound_files':files,'publication_allowlist':['summary.json','summary.md'],'private_paths_and_raw_sources_must_not_be_published':True})
print(json.dumps({'summary_sha256':sha(O/'summary.json'),'freeze_sha256':sha(O/'author-freeze.json'),'elapsed_seconds':summary['elapsed_seconds'],'pages_read':len(read),'pages_viewed':len(view),'source_copies':summary['source_copies'],'unique_source_contents':len(sources),'files':len(files)},indent=2))
